const fs=require('fs'),assert=require('assert/strict'),crypto=require('crypto');const {load}=require('./load-ts.cjs');const posts=load('lib/dailyPosts20261101.ts').DAILY_POSTS_20261101;const all=load('lib/blogPosts.ts').BLOG_POSTS;const base='https://www.11plusexampapers.com';
assert.equal(posts.length,5);assert.equal(new Set(all.map(p=>p.slug)).size,all.length);let questions=0;
for(const p of posts){const html=fs.readFileSync('.next/server/app/blog/'+p.slug+'.html','utf8');assert(html.includes('rel="canonical" href="'+base+'/blog/'+p.slug+'"'));assert(!html.includes('content="noindex'));assert(html.includes('property="og:image" content="'+base+p.imageUrl+'"'));assert(html.includes('"image":["'+base+p.imageUrl+'"]'));const hub=fs.readFileSync('.next/server/app/subjects/'+p.subject+'.html','utf8');assert(hub.includes('/blog/'+p.slug));assert(p.content.some(b=>b.text?.includes('/subjects/'+p.subject+')')));for(const b of p.content){for(const target of (b.text||'').matchAll(/\]\((\/[^)]+)\)/g)){const path=target[1];assert(fs.existsSync('.next/server/app'+path+'.html')||fs.existsSync('.next/server/app'+path+'/index.html')||Object.keys(require('../.next/server/app-paths-manifest.json')).some(k=>k===path+'/page'),'Missing '+path)}}questions+=p.content.filter(b=>b.type==='question').length;assert.equal((html.match(/<details[ >]/g)||[]).length,p.content.filter(b=>b.type==='question').length);assert(!html.includes('<details open'));}
assert.equal(questions,34);
// Independently evaluate the two arithmetic methods used in the guide.
for(const [a,b,want] of [[326,24,7824],[407,36,14652],[215,19,4085],[243,32,7776],[508,47,23876],[28,36,1008],[164,23,3772],[1206,15,18090],[38,99,3762]]){assert.equal(a*b,want);assert.equal(a*(b%10)+a*Math.floor(b/10)*10,want)}
function roman(n){let out='';for(const [v,s] of [[1000,'M'],[900,'CM'],[500,'D'],[400,'CD'],[100,'C'],[90,'XC'],[50,'L'],[40,'XL'],[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']])while(n>=v){out+=s;n-=v}return out}
function arabic(s){const v={I:1,V:5,X:10,L:50,C:100,D:500,M:1000};return [...s].reduce((n,c,i)=>n+(v[c]<(v[s[i+1]]||0)?-v[c]:v[c]),0)}
for(const [n,s] of [[662,'DCLXII'],[496,'CDXCVI'],[748,'DCCXLVIII'],[2027,'MMXXVII'],[45,'XLV'],[94,'XCIV'],[684,'DCLXXXIV'],[1948,'MCMXLVIII'],[59,'LIX'],[61,'LXI'],[62,'LXII'],[99,'XCIX'],[409,'CDIX']]){assert.equal(roman(n),s);assert.equal(arabic(s),n)}
assert.equal(28+17,45);assert.equal(38+24,62);assert.notEqual(roman(99),'IC');
// Prevent the independently identified ambiguous parcel-reference draft recurring.
assert(posts[2].content.some(b=>b.text?.includes('I wrapped the parcel and put it beside the basket')));
assert(!JSON.stringify(posts[2]).includes('It was wrapped in blue paper'));
const inv=fs.readFileSync('docs/releases/url-inventory-2026-11-01.txt','utf8').trim().split('\n');const sitemap=fs.readFileSync('.next/server/app/sitemap.xml.body','utf8');for(const u of [...inv,...posts.map(p=>base+'/blog/'+p.slug)])assert(sitemap.includes('<loc>'+u+'</loc>'));assert.equal((sitemap.match(/<loc>/g)||[]).length,246);assert(!/\/(quiz|lesson-preview|test|api)[/<]/.test(sitemap));
for(const x of JSON.parse(fs.readFileSync('docs/artwork/blog-artwork-2026-11-01.json')).items){for(const a of [x.asset,x.thumbnail])assert.equal(crypto.createHash('sha256').update(fs.readFileSync(a.path)).digest('hex'),a.sha256)}console.log('PASS five pages;34 questions;independent multiplication/Roman conversions;canonical/social/schema;reciprocal hubs/internal targets;246 sitemap URLs;10 artwork hashes');
